<?php require 'includes/auth.php';require 'config/database.php';require 'includes/csrf.php';if($_SERVER['REQUEST_METHOD']==='POST'){check();$pdo->prepare('INSERT INTO releases(prisoner_id,expected_date,actual_date,remarks,status) VALUES(?,?,?,?,?)')->execute([$_POST['prisoner_id'],$_POST['expected_date'],$_POST['actual_date'],trim($_POST['remarks']),trim($_POST['status'])]);header('Location: releases.php');exit;}$rows=$pdo->query('SELECT * FROM releases ORDER BY id DESC')->fetchAll();$title='Releases';require 'includes/header.php';?><div class="row g-4"><div class="col-lg-4"><div class="box"><h4>Add Releases</h4><form method="post"><input type="hidden" name="token" value="<?=token()?>"><label class="form-label mt-2">Prisoner ID</label><input class="form-control" type="number" name="prisoner_id" required><label class="form-label mt-2">Expected Date</label><input class="form-control" type="date" name="expected_date" required><label class="form-label mt-2">Actual Date</label><input class="form-control" type="date" name="actual_date" required><label class="form-label mt-2">Remarks</label><input class="form-control" type="text" name="remarks" required><label class="form-label mt-2">Status</label><input class="form-control" type="text" name="status" required><button class="btn btn-primary mt-3">Save</button></form></div></div><div class="col-lg-8"><div class="box"><h2>Releases</h2><div class="table-responsive"><table class="table"><tr><th>Prisoner ID</th><th>Expected Date</th><th>Actual Date</th><th>Remarks</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['prisoner_id'])?></td><td><?=htmlspecialchars($r['expected_date'])?></td><td><?=htmlspecialchars($r['actual_date'])?></td><td><?=htmlspecialchars($r['remarks'])?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;?></table></div></div></div></div><?php require 'includes/footer.php';?>